@media (max-width: 900px) {
  .docs-body {
    grid-template-columns: minmax(0, 1fr);
  }

  .docs-toc {
    /* 移动端大纲是横向折叠条（不是抽屉），保持原样式、不做 sticky */
    position: static;
    top: auto;
    max-height: none;
    overflow: visible;
    flex-direction: row;
